css:
.absolute {
  position: absolute;
}
.relative {
  position: relative;
}
.left-0 {
  left: 0px;
}
.left-1\/2 {
  left: 50%;
}
.top-0 {
  top: 0px;
}
.top-1\/2 {
  top: 50%;
}
.flex {
  display: flex;
}
.h-\[1\.5em\] {
  height: 1.5em;
}
.h-\[10em\] {
  height: 10em;
}
.h-\[12em\] {
  height: 12em;
}
.h-\[3em\] {
  height: 3em;
}
.w-\[1\.5em\] {
  width: 1.5em;
}
.w-\[16em\] {
  width: 16em;
}
.w-\[18em\] {
  width: 18em;
}
.w-\[3em\] {
  width: 3em;
}
.-translate-x-1\/2 {
  --tw-translate-x: -50%;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.-translate-y-1\/2 {
  --tw-translate-y: -50%;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.translate-y-\[100\%\] {
  --tw-translate-y: 100%;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.cursor-pointer {
  cursor: pointer;
}
.flex-col {
  flex-direction: column;
}
.items-center {
  align-items: center;
}
.justify-center {
  justify-content: center;
}
.justify-between {
  justify-content: space-between;
}
.overflow-hidden {
  overflow: hidden;
}
.rounded-\[1\.5em\] {
  border-radius: 1.5em;
}
.border-\[1px\] {
  border-width: 1px;
}
.border-\[\#ffffffaa\] {
  border-color: #ffffffaa;
}
.border-\[rgba\(107\2c 33\2c 168\2c 1\)\] {
  border-color: rgba(107, 33, 168, 1);
}
.bg-\[\#8988885c\] {
  background-color: #8988885c;
}
.bg-\[rgba\(107\2c 33\2c 168\2c 0\.24\)\] {
  background-color: rgba(107, 33, 168, 0.24);
}
.p-\[1\.5em\] {
  padding: 1.5em;
}
.text-center {
  text-align: center;
}
.text-\[0\.7em\] {
  font-size: 0.7em;
}
.text-\[0\.9em\] {
  font-size: 0.9em;
}
.text-\[1\.5em\] {
  font-size: 1.5em;
}
.text-\[2em\] {
  font-size: 2em;
}
.font-black {
  font-weight: 900;
}
.font-bold {
  font-weight: 700;
}
.font-light {
  font-weight: 300;
}
.leading-\[0\.8em\] {
  line-height: 0.8em;
}
.text-\[hsl\(0\2c 0\%\2c 85\%\)\] {
  --tw-text-opacity: 1;
  color: hsl(0 0% 85% / var(--tw-text-opacity));
}
.text-lime-300 {
  --tw-text-opacity: 1;
  color: rgb(190 242 100 / var(--tw-text-opacity));
}
.text-purple-950 {
  --tw-text-opacity: 1;
  color: rgb(59 7 100 / var(--tw-text-opacity));
}
.underline {
  -webkit-text-decoration-line: underline;
  text-decoration-line: underline;
}
.backdrop-blur-\[6px\] {
  --tw-backdrop-blur: blur(6px);
  -webkit-backdrop-filter: var(--tw-backdrop-blur) var(--tw-backdrop-brightness)
    var(--tw-backdrop-contrast) var(--tw-backdrop-grayscale)
    var(--tw-backdrop-hue-rotate) var(--tw-backdrop-invert)
    var(--tw-backdrop-opacity) var(--tw-backdrop-saturate)
    var(--tw-backdrop-sepia);
  backdrop-filter: var(--tw-backdrop-blur) var(--tw-backdrop-brightness)
    var(--tw-backdrop-contrast) var(--tw-backdrop-grayscale)
    var(--tw-backdrop-hue-rotate) var(--tw-backdrop-invert)
    var(--tw-backdrop-opacity) var(--tw-backdrop-saturate)
    var(--tw-backdrop-sepia);
}
.duration-300 {
  transition-duration: 300ms;
}
.duration-\[500ms\] {
  transition-duration: 500ms;
}
.hover\:h-\[10em\]:hover {
  height: 10em;
}
.hover\:w-\[16em\]:hover {
  width: 16em;
}
.hover\:rounded-\[1\.5em\]:hover {
  border-radius: 1.5em;
}
.group:hover .group-hover\:translate-y-0 {
  --tw-translate-y: 0px;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.group:hover .group-hover\:opacity-0 {
  opacity: 0;
}
